export function FieldCB_StopPuttingAwayDecorations(): any {
  let taskId: any = null;

      FadeInFromBlack();
      DrawDialogueFrame(0, TRUE);
      InitDecorationActionsWindow();
      taskId = CreateTask(Task_ReinitializeDecorationMenuHandler, 8);
      gTasks[taskId].tState = 0;
}

