export function InitializeCameraSprite1(sprite: any): any {
  sprite.data[0]++;
      sprite.data[0] &= 0x1F;
      if (sprite.data[0] > 15)
          sprite.invisible = TRUE;
      else
          sprite.invisible = FALSE;
}

